"""Offline Main-adoption workbench; original captures/artwork are read only.

Reuses the bounded P07 UI as its established workbench template. Final builds
require explicit released evidence; --draft writes a separate pending preview.
Browser QA belongs to Root and must bind the final generated bytes.
"""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
import re
import sys
from urllib.parse import quote

from PIL import Image

ROOT = Path(__file__).resolve().parents[3]
BASE = ROOT / "output/grafik_20261101"
HERE = BASE / "main_adoption"
ART = ROOT / "docs/reports/assets/grafik-2026-11-01"
sys.path.insert(0, str(BASE))
from build_pass07_report import PAGE as PREVIOUS_PAGE, derivative

ARCHIVE_SHA = "9b24e1089961ad58c6f21dcb99f7fd299458e755469114bd066be946f96c03c0"
REPORT_ID = "grafik_20261101_main_adoption_ref03_v1"
PAIRS = [("cutlass_front", "Cutlass · vorn", "target_cutlass_front"),
         ("cutlass_rear", "Cutlass · Heck", "target_cutlass_rear"),
         ("buccaneer_front", "Buccaneer · vorn", "target_buccaneer_front"),
         ("buccaneer_rear", "Buccaneer · Heck", "target_buccaneer_rear"),
         ("closed_outpost", "Außenposten · geschlossen", "ref_tactical"),
         ("overview", "Außenposten · Schnitt", "ref_tactical")]
SHIP_TARGETS = [("target_cutlass_front", "08_cutlass_vorne_wimmel.png", "Cutlass · 2D vorn"),
                ("target_cutlass_rear", "09_cutlass_hinten_wimmel.png", "Cutlass · 2D Heck"),
                ("target_buccaneer_front", "13_buccaneer_vorne_wimmel_vereinfacht.png", "Buccaneer · 2D vorn"),
                ("target_buccaneer_rear", "11_buccaneer_hinten_wimmel.png", "Buccaneer · 2D Heck")]
CAMERA_FIELDS = ("camera_size", "camera_transform", "camera_projection", "viewport_size", "building_shells_visible")


def read(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8-sig"))


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def local(path: str) -> Path:
    return ROOT / path.removeprefix("res://")


def optional(path: Path) -> dict:
    return read(path) if path.is_file() else {}


def prepare(args) -> dict:
    archive = ROOT / "docs/reports/STERNENBUERGERCHEN_GRAFIK_PASS07_2026-11-01.html"
    assert sha(archive) == ARCHIVE_SHA, "Historical P07 HTML must remain byte-identical"
    before = read(BASE / "pass07_paths_after_capture.json")
    history = read(BASE / "pass07_paths_verification_manifest.json")
    old_hashes = {r["id"]: r["sha256"] for r in history["capture_records"] if r.get("evidence_kind") == "art_fixture"}
    after = optional(args.preview_metadata)
    runtime = optional(args.runtime_metadata)
    verification = optional(args.verification)
    menu = optional(HERE / "menu_background_capture.json")
    pending = []
    if after.get("report_ready") is not True:
        pending.append("Finale Preview-Captures noch nicht freigegeben")
    if not runtime:
        pending.append("Echte Menü-/Homebase-/Missionsbelege noch ausstehend")
    if not verification:
        pending.append("Versionsgebundener Prüf-/Mainnachweis noch ausstehend")
    if not args.draft:
        assert not pending, pending
    assets = []

    def add(identifier, path, title, group, status, description, **extra):
        file = local(path)
        exists = file.is_file()
        if not exists and not args.draft:
            raise FileNotFoundError(file)
        dimensions, thumb, full, digest = [], "", "", ""
        if exists:
            with Image.open(file) as image:
                dimensions = list(image.size)
            digest = sha(file)
            thumb, full = derivative(file, 520, 78), derivative(file, 1800, 86)
        else:
            status = "AUSSTEHEND · " + status
            full = thumb = "data:image/svg+xml," + quote('<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="900"><rect width="1600" height="900" fill="#ddd8c8"/><text x="800" y="450" text-anchor="middle" fill="#193f40" font-size="58">Aufnahme ausstehend</text></svg>')
        assets.append({"id": identifier, "path": file.relative_to(ROOT).as_posix(), "title": title,
                       "group": group, "status": status, "description": description, "exists": exists,
                       "sha256": digest, "dimensions": dimensions, "thumb": thumb, "full": full, **extra})

    references = read(BASE / "reference_manifest.json")["current_user_references"]
    for row in references:
        assert sha(local(row["package_path"])) == row["sha256"]
        add(row["id"], row["package_path"], row["title"], "targets", "2D-Nutzerziel · keine native Aufnahme",
            row["description"] + " " + row["limits"], origin=row["origin"], source_original_path=row["source_path"])
    for identifier, filename, title in SHIP_TARGETS:
        add(identifier, str((ART / filename).relative_to(ROOT)), title, "targets", "Generierte 2D-Zielvorlage · Wimmelbild / vereinfacht",
            "Aktuelles zugeordnetes Schiffsziel. Illustration und native Kamera sind unterschiedlich; Modellintegration bedeutet keine perfekte 2D-Rekonstruktion.")
    old_cameras = {r["id"]: r for r in before["captures"]}
    new_cameras = {r["id"]: r for r in after.get("captures", [])}
    pairs = []
    for view, title, target in PAIRS:
        old = ART / "engine_pass07_paths/after" / f"{view}.png"
        new = ART / "engine_main_adoption/after" / f"{view}.png"
        assert sha(old) == old_hashes[view], "P07 before image changed: " + view
        add("before_" + view, str(old.relative_to(ROOT)), "Vorher · P07 / R02 · " + title, "before",
            "Historische native Godot-Aufnahme · R02-Schiffe wurden kritisiert", "Unveränderter P07-Ausgangsstand; keine neue Modellfreigabe.")
        add("after_" + view, str(new.relative_to(ROOT)), "Ref03 / Adoptionsstand · " + title, "after",
            "Native Godot-Aufnahme · Grafik-/Modellkontrolle", "Ref03 im tatsächlichen Grafikaufbau; diese synthetische Modellkontrolle ist keine echte Kampagnenmission.", paired=True, view=view)
        row = {"id": view, "title": title, "target_id": target, "before": str(old.relative_to(ROOT)),
               "before_sha256": sha(old), "before_camera": old_cameras[view], "after_camera": new_cameras.get(view, {}), "camera_match": False}
        if view in new_cameras:
            assert local(new_cameras[view]["path"]) == new
            assert new_cameras[view].get("error") == 0
            for key in CAMERA_FIELDS:
                assert old_cameras[view][key] == new_cameras[view][key], (view, key)
            assert after["light"] == before["light"] and after["renderer"] == before["renderer"]
            row.update(after=str(new.relative_to(ROOT)), after_sha256=sha(new), camera_match=True)
        elif not args.draft:
            raise ValueError("Missing captured camera metadata: " + view)
        pairs.append(row)
    paired_ids = {p[0] for p in PAIRS}
    for row in after.get("captures", []):
        if row["id"] not in paired_ids:
            add("after_" + row["id"], row["path"], "Adoptionskontrolle · " + row["id"], "after",
                "Native zusätzliche Grafik-Kontrollansicht", "Eigenständige Kontrollansicht außerhalb der sechs festen Paare; keine erfundene Vorher-/Missionsabnahme.", paired=False, view=row["id"])
    add("menu_background", "Assets/curated/main_menu/frontier_outpost_main_20261101.png", "Neues natives Menübild", "menu",
        "Native Projektaufnahme · Menü-Hintergrundmotiv", "Saubere native Outpostaufnahme. Der tatsächliche Menü-/Homebase-/Missionspfad wird in separaten echten Kontrollaufnahmen belegt.")
    controls = runtime.get("captures", runtime.get("runtime_controls", []))
    for row in controls:
        add("runtime_" + row["id"], row["path"], row.get("title", row["id"]), "runtime",
            "Echter normaler Startpfad · separate Aufnahme ohne Vorherpaar", row.get("description", "Tatsächlicher Menü-/Homebase-/Missionsbeleg; Fakten und erreichte Startphase nur nach dem zugehörigen Runtimeprotokoll."),
            evidence_kind="normal_start_control", has_before=False, view=row["id"])
    package = ROOT / "art/frontier_illustrated_20261101/ships/pass05_astra_ultra/refinement_03/manifest.json"
    source_packages = {"ref03": {"path": package.relative_to(ROOT).as_posix(), "sha256": sha(package), "data": read(package)}}
    if after:
        models = {row["id"]: row for row in after["models"]}
        for ship in ("cutlass", "buccaneer"):
            export = source_packages["ref03"]["data"]["assets"][ship]["export"]
            captured = models[ship + "_01"]
            assert local(captured["path"]) == local(export["path"])
            assert captured["source_sha256"] == export["sha256"] == sha(local(export["path"]))
        assert after.get("missing_asset_mapping_count") == 0
        for record in after["captures"]:
            assert record.get("error") == 0
            with Image.open(local(record["path"])) as image:
                assert image.size == (1600, 900)
    native = verification.get("native_captures", len(after.get("captures", [])) + len(controls))
    verification = {"engine_checks_passed": "ausstehend", "engine_checks_selected": "ausstehend", "native_captures": native,
                    "code_commit": "Nachweis ausstehend", "material_route": "Ref03-Modellgeometrie und Schiffsmaterialien sind Gegenstand des Vergleichs.",
                    "scope": "Aktive Startgrafik / Ref03-Adoption; echte GM01 bleibt square8, Hex-Workyard separat. Kein neues Fighter-/Schiffs-Gameplay und keine allgemeine Releaseabnahme.", **verification}
    return {"report_id": REPORT_ID, "revision": "main_adoption_ref03_v1", "pending": pending,
            "assets": assets, "pairs": pairs, "targets": [x["id"] for x in references] + [x[0] for x in SHIP_TARGETS],
            "runtime_controls": controls, "runtime_evidence": runtime, "legacy_evidence": optional(BASE / "pass07_runtime/legacy_baseline_comparison.json"),
            "source_packages": source_packages, "verification": verification, "after_metadata": after,
            "before_metadata": before, "runtime_sources_sha256": after.get("runtime_sources_sha256", {}),
            "archive_sha256": ARCHIVE_SHA, "menu_capture": menu,
            "technical": [["Problem", "Neue Grafik als normalen Startstand und Ref03-Schiffe tatsächlich übernehmen; UI danach gesondert prüfen."],
                          ["Ursache", "Die bisherige Grafikwerkstatt war vom normalen GM01-Missionsdefault und dem alten Menümotiv getrennt."],
                          ["Änderung", "Gespeichertes Frontier-Theme auf GM01, neues natives Menümotiv und Ref03-Modelle; echte Startbelege von synthetischen Modellvergleichen getrennt."],
                          ["Betroffene Dateien", "GM01-Theme, bestehender Hintergrundkatalog, Ref03-Export-/Assetmapping und Grafikaufbau; genaue Quellen in den Metadaten."],
                          ["Risiken / offene Punkte", "GM01-Fakten und square8 bleiben erhalten. Hex-Werft separat; Buccaneer statisches integriertes Modell/Katalog, kein Fighter-Gameplay. Aktive Übernahme ist keine perfekte 2D-Rekonstruktion oder Releaseabnahme."],
                          ["Lokale Prüfung", verification.get("local_checks", "Versionsgebundener Prüfnachweis noch ausstehend; keine Testzahl erfunden.")],
                          ["Git-Status / Main / Push", verification.get("git_status", "Main-/Pushstatus nur nach finalem Nachweis; noch ausstehend.")]]}


def page_template() -> str:
    page = PREVIOUS_PAGE.replace("grafik_20261101_pass07_paths_env07", REPORT_ID)
    page = page.replace("pass07_paths.env07", "main_adoption.ref03_v1")
    page = page.replace("Pass07", "Ref03 / Main-Adoption").replace("P07", "Ref03").replace("Pass06", "P07")
    page = page.replace("12 feste", "6 feste").replace("zwölf", "sechs").replace("Zwölf", "Sechs")
    page = page.replace("STERNENBUERGERCHEN_GRAFIK_PASS06_2026-11-01.html", "STERNENBUERGERCHEN_GRAFIK_PASS07_2026-11-01.html")
    page = page.replace(".pair{display:grid;grid-template-columns:1fr 1fr;", ".pair{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));")
    start = page.index('<section class="intro">')
    end = page.index('<figure class="hero">', start)
    page = page[:start] + '''<section class="intro"><div><div class="eyebrow">Startgrafik / aktive Ref03-Modelle</div><h1>Frontier als Start.<br>Die Schiffe im Spielbild.</h1></div><div><p>Neues natives Menübild und Frontier-Profil im normalen GM01-Startpfad. Vier Schiffspaare zeigen R02 gegen die tatsächlich importierte Ref03; echte Menü-/Homebase-/Missionsbelege bleiben davon getrennt.</p><div class="tags"><span class="tag">4 Schiffspaare + 2 Ensemblepaare</span><span class="tag">GM01: square8 unverändert</span><span class="tag">Hex-Werft weiter verfügbar</span></div></div></section><p id="pendingBanner" class="small" role="status"></p>''' + page[end:]
    page = page.replace('data-open="after_lived_outpost"', 'data-open="menu_background"').replace('data-src-id="after_lived_outpost"', 'data-src-id="menu_background"')
    page = re.sub(r'<figure class="hero">(.*?)<figcaption>.*?</figcaption>', r'<figure class="hero">\1<figcaption>Neues Menü-Hintergrundmotiv · saubere native Projektaufnahme. Das Outpostmotiv ist ein Grafikaufbau; der tatsächliche normale Start wird weiter unten separat belegt.</figcaption>', page, count=1, flags=re.S)
    page = page.replace("Nativer Ref03-Preview-Außenposten", "Neues natives Outpost-Menümotiv")
    page = page.replace("Wegeanschlüsse und erster regulärer Karten-Slice", "Startgrafik und Ref03-Schiffsadoption")
    page = page.replace("Ref03 / Main-Adoption Wege & Runtime", "Frontier-Start und Ref03")
    page = page.replace("Preview und begrenzter Karten-Slice", "Startgrafik und begrenzte Modelladoption")
    page = page.replace("Reguläre Karte / kein Vorherpaar", "Echter Start / ohne Vorherpaar")
    page = page.replace('href="#runtime">Reguläre Karten', 'href="#runtime">Echter Start')
    page = page.replace("Große Formen.<br>Gerichtete Spuren.", "2D bleibt der Maßstab.")
    page = page.replace("Rostgrenze, Freihafen und die taktische Gesamtkarte führen Felsstaffelung, Oberflächen und bewohnte Funktionsgruppen.", "Rostgrenze, Freihafen und die taktische Karte führen die Umgebung; vier eigene Schiffsansichten führen Cutlass und Buccaneer.")
    page = page.replace("P07 → Ref03 / Main-Adoption / gleiche native Kameras", "P07 / R02 → Ref03 / gleiche native Kameras")
    page = page.replace("Wege, Anschlussflächen und konkrete Grafikfehler sind Gegenstand dieses Vergleichs. Schiffs-, Citizen- und originale Kenney-Dateien bleiben unverändert.", "Ref03-Geometrie und Schiffsmaterialien sind Gegenstand des Vergleichs. 2D und native Kamera sind unterschiedliche Darstellungen; ihre Nähe bleibt ein eigenes Nutzerurteil.")
    page = page.replace('id="pairSide" class="pair">', 'id="pairSide" class="pair"><figure><div class="pair-label">2D-Ziel · abweichende Kamera</div><button type="button" id="pairTargetButton" class="image-button"><img id="pairTargetImage" alt="Zugeordnetes 2D-Ziel"><span class="cue">2D-Ziel vergrößern ↗</span></button><figcaption id="pairTargetCaption"></figcaption></figure>')
    page = page.replace("Eingangsmitte, letzter Wegabschnitt, Rampe, Markierungen …", "Silhouette, vier Triebwerke, Cockpitwanne, Materialgewicht …")
    start = page.index('<section class="section" id="runtime">')
    end = page.index('<section class="section" id="quellen">', start)
    page = page[:start] + '''<section class="section" id="runtime"><div class="section-head"><div><div class="eyebrow">Echter normaler Startpfad</div><h2>Menü, Homebase und Mission.</h2></div><p>Diese separaten nativen Bilder stammen aus dem normalen Einstieg. GM01 behält square8 und seine Missions-/LZ-/Rosterfakten; die Hex-Werft bleibt separat. Keine Previewansicht wird als echte Mission ausgegeben.</p></div><p id="runtimePending" class="small"></p><label>Startphase / Kontrollansicht<select id="runtimeSelect"></select></label><figure id="runtimeFrame" class="reference-frame"><button type="button" id="runtimeButton" class="image-button"><img id="runtimeImage" alt="Echte Startkontrolle"><span class="cue">Kontrollaufnahme vergrößern ↗</span></button><figcaption id="runtimeCaption"></figcaption></figure><p id="runtimeLimits" class="small">Die tatsächlich erreichte LZ-/Deployment-/GO-Phase steht im Runtimeprotokoll. Ein einzelnes Bild oder ein grüner Grafikcheck ist keine volle Teamankunfts-, Combat-, Performance- oder Releaseabnahme. Buccaneer ist hier ein integriertes statisches Modell im Katalog, kein Fighter-Gameplay.</p><details><summary>Originaler Runtime-Nachweis / Startphase</summary><pre id="runtimeMapFacts"></pre></details></section>''' + page[end:]
    start = page.index('<section class="section" id="quellen">')
    end = page.index('<section class="section" id="bilder">', start)
    page = page[:start] + '''<section class="section" id="quellen"><div class="section-head"><div><div class="eyebrow">Quellen, Umfang und Status</div><h2>Was übernommen wird.</h2></div><p>Aktive Integration, technische Prüfung und perfekte Rekonstruktion der 2D sind getrennte Aussagen. Der versionsgebundene Main-/Pushstatus steht im technischen Nachweis; frühere Stände bleiben archiviert.</p></div><div class="source-grid"><article><div class="eyebrow">Normaler Start</div><h3>Ein gespeichertes Theme.</h3><p>GM01 verwendet frontier_illustrated_v1. Alle anderen Kartenbytes und das Szenario bleiben unverändert; Defaulttopologie ist weiterhin square8. Das neue Menümotiv nutzt denselben Katalogplatz und die vorhandene Textrail.</p><p><a href="../../output/grafik_20261101/main_adoption/menu_background_capture.json">Menüaufnahme / Herkunft ↗</a></p></article><article><div class="eyebrow">Astra Ref03</div><h3>Neue aktive Schiffgeometrie.</h3><p>Cutlass mit vier Triebwerken und schmaleren Vorderflügeln; Buccaneer mit geschlossener unterer Cockpitwanne. Quellen, Texturen, Exporthashes und Prüfgrenzen bleiben im Ref03-Paket. Displaymaßstab ist bewusst stilisiert.</p><p><a href="../../art/frontier_illustrated_20261101/ships/pass05_astra_ultra/refinement_03/manifest.json">Ref03-Quellen / Audits ↗</a></p></article><article><div class="eyebrow">Geschichte / Grenzen</div><h3>R02 bleibt als Vorher erhalten.</h3><p>R02 war nutzerkritisiert; die Übernahme von Ref03 bedeutet keine perfekte 2D-Rekonstruktion. Keine neue Schiffs-, Fighter- oder Innenraumsimulation. UI wird anschließend gesondert angesehen.</p><p><a href="STERNENBUERGERCHEN_GRAFIK_PASS07_2026-11-01.html">Bytegleiches P07-Archiv / bisherige Galerien ↗</a></p></article></div><p class="small" id="nativeSummary"></p><p class="small" id="legacyLimits">Bekannte rote Altprüfungen und frühere Releasegrenzen sind im P07-Bericht samt Baselineprotokollen dokumentiert. Diese Grafikadoption ersetzt keine allgemeine Spiel-/Releaseabnahme.</p><details id="technicalDetails"><summary>Problem, Ursache, Dateien, Risiken, lokale Prüfung und Mainstatus</summary><div class="table-scroll"><table><tbody id="technicalRows"></tbody></table></div></details><details><summary>Aktuelle Runtime-/Karten-/Kataloghashes</summary><div class="table-scroll"><table><tbody id="runtimeRows"></tbody></table></div></details><p class="small"><a href="../../docs/tasks/ART_2026_11_01_main_graphics_adoption.md">Auftrag ↗</a> · <a href="../../output/grafik_20261101/main_adoption/verification_manifest.json">Versionsgebundener Nachweis ↗</a></p></section>''' + page[end:]
    page = page.replace('<label>Gesamturteil und nächste konkrete Bildkorrektur', '<div class="note-grid"><label>Eigener Playteststand<select id="playtestStatus"><option value="not_reviewed">Noch nicht selbst geprüft</option><option value="menu_homebase">Menü / Homebase angesehen</option><option value="mission_lz">Mission / LZ geprüft</option><option value="deployment_go">Deployment / GO geprüft</option><option value="needs_revision">Konkrete Überarbeitung nötig</option></select></label><label>Playtestbeobachtung<textarea id="playtestNote"></textarea></label></div><label>Gesamturteil und nächste konkrete Bildkorrektur')
    page = page.replace("const state={runtimeView:", "const state={playtest:typeof stored.playtest==='string'?stored.playtest:'not_reviewed',playtestNote:typeof stored.playtestNote==='string'?stored.playtestNote:'',runtimeView:")
    page = page.replace("stored.view:'lived_outpost'", "stored.view:'cutlass_front'")
    page = page.replace("${['Rostgrenze','Freihafen','Taktische Karte'][i]}", "${esc(byId[id].title)}")
    marker = "function renderPair(){const p=DATA.pairs.find(p=>p.id===state.view),a=byId['before_'+p.id],b=byId['after_'+p.id];"
    page = page.replace(marker, marker + "const t=byId[p.target_id];$('#pairTargetImage').src=t.full;$('#pairTargetImage').alt=t.title;$('#pairTargetButton').dataset.open=t.id;$('#pairTargetCaption').textContent=t.title+' · 2D-Ziel, abweichende Kamera.';state.target=t.id;renderTarget();")
    page = page.replace("'Gleiche Kamera / '+a.dimensions.join(' × ')", "(p.camera_match?'Gleiche native Kamera / ':'Kamera-Nachweis ausstehend / ')+a.dimensions.join(' × ')")
    page = page.replace("DATA.after_metadata.renderer", "(DATA.after_metadata.renderer||'Nachweis ausstehend')")
    page = page.replace("Wege-/Anschlusskorrekturen", "Ref03-Geometrie / Schiffsmaterialien")
    start = page.index("function renderRuntime()")
    end = page.index("function filtered()", start)
    page = page[:start] + "function renderRuntime(){const r=DATA.runtime_controls.find(r=>r.id===state.runtimeView);$('#runtimePending').textContent=r?'Neue echte Startkontrolle ohne erfundenes Vorherpaar.':'Echte Start-Captures sind noch ausstehend.';$('#runtimeFrame').hidden=!r;$('#runtimeSelect').disabled=!r;if(!r)return;const a=byId['runtime_'+r.id];$('#runtimeSelect').value=r.id;$('#runtimeImage').src=a.full;$('#runtimeImage').alt=a.title;$('#runtimeButton').dataset.open=a.id;$('#runtimeCaption').textContent=a.title+' · '+a.status+' · '+a.description;$('#runtimeMapFacts').textContent=JSON.stringify({capture:r,evidence:DATA.runtime_evidence},null,2);}\n" + page[end:]
    page = page.replace("$('#searchInput').value=state.query;", "$('#pendingBanner').textContent=DATA.pending.length?'AUSSTEHEND: '+DATA.pending.join(' · '):'Aktueller Adoptionsstand · technische und gestalterische Grenzen siehe Nachweis.';$('#playtestStatus').value=state.playtest;$('#playtestNote').value=state.playtestNote;$('#playtestStatus').addEventListener('change',e=>{state.playtest=e.target.value;save();});$('#playtestNote').addEventListener('input',e=>{state.playtestNote=e.target.value;save();});$('#searchInput').value=state.query;")
    page = page.replace("'Original: '+a.dimensions.join(' × ')+' px · WebP ist eine Anzeigekopie.'", "a.exists?'Original: '+a.dimensions.join(' × ')+' px · WebP ist eine Anzeigekopie.':'Originalaufnahme noch ausstehend.'")
    page = page.replace("controls:{comparison:", "controls:{playtest:state.playtest,comparison:")
    page = page.replace("notes:{comparison:", "notes:{playtest:state.playtestNote,comparison:")
    page = page.replace("primary_glbs_unchanged:true,raw_stock_sources_unchanged:true,legacy_campaign_migrated:false", "primary_glbs_unchanged:false,default_grid_topology:'square8',hex_workyard_available:true,main_integrated:DATA.verification.main_integrated===true,legacy_campaign_migrated:false")
    page = page.replace("archive_pass06_sha256", "archive_pass07_sha256")
    page = page.replace("a.group==='before'?'P07 / Vorher':", "a.group==='before'?'P07 / Vorher':a.group==='menu'?'Neues Menümotiv':")
    page = page.replace("group:['all','targets','before','after','runtime']", "group:['all','targets','before','after','runtime','menu']")
    page = page.replace('<button type="button" data-group="runtime" aria-pressed="false">Reguläre Karten</button>', '<button type="button" data-group="runtime" aria-pressed="false">Echter Start</button><button type="button" data-group="menu" aria-pressed="false">Menümotiv</button>')
    page = re.sub(r"\$\('#nativeSummary'\)\.textContent=.*?;\n", "$('#nativeSummary').textContent=DATA.verification.engine_checks_passed+'/'+DATA.verification.engine_checks_selected+' Prüfwerte laut versionsgebundenem Nachweis · '+DATA.verification.native_captures+' native Aufnahmen · 6 feste Grafikpaare · '+DATA.runtime_controls.length+' echte Startkontrollen · Code '+DATA.verification.code_commit+'. Keine allgemeine Releaseabnahme.';\n", page, count=1)
    return page


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--draft", action="store_true")
    parser.add_argument("--validate-only", action="store_true")
    parser.add_argument("--preview-metadata", type=Path, default=BASE / "main_adoption_after_capture.json")
    parser.add_argument("--runtime-metadata", type=Path, default=BASE / "main_adoption_runtime/native_final.json")
    parser.add_argument("--verification", type=Path, default=HERE / "verification_manifest.json")
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()
    data = prepare(args)
    if args.validate_only:
        print(json.dumps({"pending": data["pending"], "assets": len(data["assets"]), "pairs": len(data["pairs"])}))
        return
    output = args.output or (HERE / "report_draft.html" if args.draft else ROOT / "docs/reports/STERNENBUERGERCHEN_GRAFIK_2026-11-01.html")
    payload = json.dumps(data, ensure_ascii=False, separators=(",", ":")).replace("<", "\\u003c")
    output.write_bytes(page_template().replace("__DATA__", payload).encode("utf-8"))
    print(json.dumps({"output": str(output), "sha256": sha(output), "bytes": output.stat().st_size, "pending": data["pending"]}))


if __name__ == "__main__":
    main()
